import java.util.*;
import java.io.*;

public class HeightAllTheSame {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        long N = dis.readLong();
        long M = dis.readLong();
        long L = dis.readLong();
        long R = dis.readLong();
        long total = N * M;
        long range = R - L + 1;
        long result;
        if (total % 2 == 1) {
            result = fastExponentiation(range, total, 998244353);
        } else if (range % 2 == 0) {
            result = (fastExponentiation(range, total, 998244353) * (998244353 + 1) / 2) % 998244353;
        } else {
            result = ((fastExponentiation(range, total, 998244353) + 1) * (998244353 + 1) / 2) % 998244353;
        }
        System.out.println(result);
        dis.close();
    }

    static long fastExponentiation(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}
